mapper.select:
select video.*, content.id as ptChannelContentId, video_content.id as videoId from gc_video video_content JOIN sys_file video ON video_content.file_id = video.id left join pt_channel_content content on content.content_id = video_content.id where content.channel_id =#{channelId} group by video.id, content.id, video_content.id
order by convert_to(video_content.video_name, 'UTF8') ${order}
order by content.content_order asc
